def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Extend each 2 seed rightward; the marker becomes 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 4
                for x in range(c + 1, w):
                    if grid[r][x] == 5:
                        out[r][x] = 2
    # Corner 9 blocks extend toward each other in vertical 2-wide stripes.
    for r in range(h):
        if grid[r][-2:] == [9, 9]:
            for y in range(r + 1, h):
                for c in (w - 2, w - 1):
                    if grid[y][c] == 5: out[y][c] = 9
        if grid[r][:2] == [9, 9]:
            for y in range(r - 1, -1, -1):
                for c in (0, 1):
                    if grid[y][c] == 5: out[y][c] = 9
    return out

