def transform(grid):
    out = [row[:] for row in grid]
    # Marker pairs at opposite corners project a solid fill along their inward
    # directions; sparse 7 markers become 4 in the demo's diagonal pattern.
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    for r in range(h):
        for c in range(w-1):
            if grid[r][c:c+2] == [2, 2]:
                for rr in range(r+1, h):
                    for cc in (c,c+1):
                        if out[rr][cc] == bg: out[rr][cc] = 7
    for r in range(h-1):
        for c in range(w):
            if grid[r][c] == grid[r+1][c] == 2:
                for rr in (r,r+1):
                    for cc in range(c+1,w):
                        if out[rr][cc] == bg: out[rr][cc] = 7
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 7: out[r][c] = 4
    return out

